using System;using System.Collections.Generic;using System.Drawing;using System.IO;using System.Linq;using System.Text;using System.Windows.Forms;
namespace XzyBattleStats {
static class Aggregation {
public static Snapshot Create(IEnumerable<Snapshot> sources){var ss=sources.GroupBy(Merge.Key).Select(g=>{Snapshot combined=null;foreach(var s in g)combined=Merge.Combine(combined,s).Data;return combined;}).OrderBy(Merge.Key,StringComparer.Ordinal).ToList();if(ss.Count==0)throw new Exception("至少选择一个账号赛季。");if(ss.Any(s=>s.Demo)&&ss.Any(s=>!s.Demo))throw new Exception("演示数据与真实数据不能一起汇总。");var result=new Snapshot{Format="XZY-BattleView",Name=ss.Select(s=>s.GameCode+"|"+s.Uid).Distinct().Count()+" 个账号",Uid="",GameCode="多区服",SeasonName="跨账号 / 赛季汇总",SeasonStart=ss.Min(s=>s.SeasonStart),SeasonEnd=ss.Max(s=>s.SeasonEnd),DataAsOf=ss.Max(s=>s.DataAsOf),ListComplete=ss.All(s=>s.ListComplete),Demo=ss[0].Demo,ViewSources=ss};foreach(var s in ss){result.ImportSources.AddRange(s.ImportSources);result.Warnings.AddRange(s.Warnings.Select(w=>s.Name+" / "+s.SeasonName+"："+w));foreach(var b in s.Battles){var copy=J.Json.Deserialize<Battle>(J.Json.Serialize(b));copy.ViewSourceKey=Merge.Key(s);copy.ViewSourceLabel=s.Name+" / "+s.SeasonName+" / "+s.GameCode;copy.ViewGameCode=s.GameCode;copy.OriginalId=b.Id;copy.Id=ss.IndexOf(s)+"|"+b.Id;result.Battles.Add(copy);}}result.Warnings.Insert(0,"按账号记录累计；同一对局若被多个账号导入，各账号分别计一次。");return result;}
}
sealed partial class NativeForm {
List<Snapshot> ReadSources(){var map=new Dictionary<string,Snapshot>();var dir=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"data");var inputs=new List<Snapshot>();if(Directory.Exists(dir))foreach(var file in Directory.GetFiles(dir,"*.json"))inputs.AddRange(Stats.DecodeMany(file));if(data!=null)inputs.AddRange(data.IsAggregate?data.ViewSources:new List<Snapshot>{data});foreach(var s in inputs){string key=Merge.Key(s);Snapshot old;map[key]=Merge.Combine(map.TryGetValue(key,out old)?old:null,s).Data;}return map.Values.OrderByDescending(s=>s.SeasonStart).ThenBy(s=>s.Name).ToList();}
void SelectAggregate(){var available=ReadSources();if(available.Count==0)throw new Exception("请先导入需要汇总的账号和赛季战绩。");if(available.Any(s=>!s.Demo))available=available.Where(s=>!s.Demo).ToList();var previous=data!=null&&data.IsAggregate?new HashSet<string>(data.ViewSources.Select(Merge.Key)):null;using(var dialog=new Form{Text="选择汇总的账号和赛季",Width=850,Height=610,MinimumSize=new Size(650,420),StartPosition=FormStartPosition.CenterParent,Font=new Font("Microsoft YaHei UI",10),BackColor=BackColor,ForeColor=ForeColor}){var list=new CheckedListBox{Dock=DockStyle.Fill,CheckOnClick=true,BackColor=BackColor,ForeColor=ForeColor};foreach(var s in available)list.Items.Add(s.Name+" / "+s.SeasonName+" / "+s.GameCode+" · "+s.Battles.Count+" 场 · 账号 "+s.Uid,previous==null||previous.Contains(Merge.Key(s)));dialog.Controls.Add(list);var note=new Label{Text="按账号记录累计；同一局在多个账号中分别计数。分数图按账号、赛季分别显示。",Dock=DockStyle.Top,Height=55,Padding=new Padding(12)};dialog.Controls.Add(note);var tools=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=60,Padding=new Padding(8)};tools.Controls.Add(Action("全部选择",()=>{for(int i=0;i<list.Items.Count;i++)list.SetItemChecked(i,true);}));tools.Controls.Add(Action("全部清除",()=>{for(int i=0;i<list.Items.Count;i++)list.SetItemChecked(i,false);}));var confirm=new Button{Text="开始汇总",AutoSize=true,Padding=new Padding(12,6,12,6)};confirm.Click+=delegate{if(list.CheckedIndices.Count==0){MessageBox.Show(dialog,"至少选择一个账号赛季。");return;}dialog.DialogResult=DialogResult.OK;};tools.Controls.Add(confirm);dialog.Controls.Add(tools);if(dialog.ShowDialog(this)!=DialogResult.OK)return;data=Aggregation.Create(list.CheckedIndices.Cast<int>().Select(i=>available[i]));Render();}}
void FillMateChoices(){var selected=Chosen(teamUid);teamUid.Items.Clear();teamUid.Items.Add(new Choice{Id="",Name="全部队友"});if(data!=null){var choices=Stats.Teammates(data,mode).OrderByDescending(t=>t.Games).ThenBy(t=>t.Name).ThenBy(t=>t.Identity,StringComparer.Ordinal).ToList();var numbers=new Dictionary<string,int>();foreach(var t in choices){int n;numbers.TryGetValue(t.Name,out n);numbers[t.Name]=n+1;teamUid.Items.Add(new Choice{Id="@mate:"+t.Identity,Name=t.Name+(choices.Count(x=>x.Name==t.Name)>1?"（同名 "+(n+1)+"）":"")+" · "+t.Games+" 场"});}}teamUid.SelectedIndex=0;for(int i=0;i<teamUid.Items.Count;i++)if(((Choice)teamUid.Items[i]).Id==selected)teamUid.SelectedIndex=i;}
void ExportAggregate(string path){if(!data.IsAggregate)throw new Exception("当前未选择汇总范围。");File.WriteAllText(path,J.Json.Serialize(new SnapshotArchive{Snapshots=data.ViewSources}),new UTF8Encoding(false));}
}
}
